-- Brazilian club jerseys from SKU-specific supplier pages verified in November 2026.
-- Historical season is shown in titles. Only items explicitly sold out are flagged sold_out.
INSERT INTO public.external_offers (id,title,description,store_name,category,sport,price,original_price,image_url,source_url,image_urls,variant_options,team_id,is_active,stock_status)
SELECT v.* FROM (VALUES
('club-soldout-sada-cruzeiro-finta-i-white','Camisa Oficial I Sada Cruzeiro Vôlei Clube Finta Branca Masculina','Camisa de jogo oficial I Sada Cruzeiro, branca, masculina, Finta 7CM101. Produto esgotado na Dafiti; preço no cartão informado na página consultada em novembro de 2026. Modelo de coleção anterior, não apresentado como lançamento 2026/27.','Dafiti','Vestuário','Vôlei',116.13,139.9,'https://static.dafiti.com.br/p/finta-camisa-oficial-i-sada-cruzeiro-v%C3%B4lei-clube-c%2Fn-branca-1216-8314211-1-zoom.jpg?ims=fit-in%2F430x623','https://www.dafiti.com.br/Camisa-Oficial-I-Sada-Cruzeiro-Volei-Clube-C%2FN-Branca-1124138.html',ARRAY['https://static.dafiti.com.br/p/finta-camisa-oficial-i-sada-cruzeiro-v%C3%B4lei-clube-c%2Fn-branca-1216-8314211-1-zoom.jpg?ims=fit-in%2F430x623']::text[],ARRAY['P','M','G','GG']::text[],'superliga-brasil-masculina-2026-27:sada-cruzeiro',true,'sold_out'),
('club-suzano-volei-2025-blue-outlet','Camiseta Oficial Suzano Vôlei 2025 Azul Masculina','Camiseta oficial Suzano Vôlei edição 2025, azul, sem número na parte frontal na versão entregue. Fotografia comercial ilustrativa do mesmo modelo; página de outlet mostra disponibilidade em cinco dias úteis. Referência de preço da loja em 23/11/2026.','Coleção Suzano Vôlei','Vestuário','Vôlei',80,119.9,'https://images.tcdn.com.br/img/img_prod/1052283/180_lanamento_camiseta_oficial_2025_azul_1_20250825100740_53e75aef8450.png','https://www.colecaosuzanovolei.com.br/camisetas/camiseta/lancamento-camiseta-oficial-2025-azul-75',ARRAY['https://images.tcdn.com.br/img/img_prod/1052283/180_lanamento_camiseta_oficial_2025_azul_1_20250825100740_53e75aef8450.png']::text[],ARRAY['PP','P','M','G','GG','G1','G2','G3']::text[],'superliga-brasil-masculina-2026-27:suzano-volei',true,'available'),
('club-osasco-nbb-2526-black','Regata Oficial Basket Osasco NBB 2025/26 Preta Sem Nome/Número','Regata oficial Basket Osasco, preta, temporada NBB 2025/26, fabricada pela Pulsa. Foto original da SKU e preço de R$149,90 verificados na loja Pulsa. Loja indicava última peça, disponibilidade sujeita a confirmação.','Pulsa Uniformes','Vestuário','Basquete',149.9,NULL::numeric,'https://acdn-us.mitiendanube.com/stores/005/557/804/products/whatsapp-image-2025-10-21-at-18-26-14-1-8ccd7f11110bcbd62117610884446260-1024-1024.webp','https://loja.usepulsa.com.br/produtos/regata-basket-osasco-nbb-25-26-preta-sem-n-sem-nome-gssrt/',ARRAY['https://acdn-us.mitiendanube.com/stores/005/557/804/products/whatsapp-image-2025-10-21-at-18-26-14-1-8ccd7f11110bcbd62117610884446260-1024-1024.webp']::text[],ARRAY['PP','P','M','G','GG','XG','G1','G2']::text[],'nbb-brasil-2026-27:basket-osasco',true,'available')
) AS v(id,title,description,store_name,category,sport,price,original_price,image_url,source_url,image_urls,variant_options,team_id,is_active,stock_status)
WHERE EXISTS(SELECT 1 FROM public.catalog_teams t WHERE t.id=v.team_id)
AND NOT EXISTS(SELECT 1 FROM public.external_offers x WHERE x.id=v.id OR x.source_url=v.source_url)
ON CONFLICT (id) DO NOTHING;
